fn main() -> Int {
  let a = 10;
  var b = 20;
  let a = a + 5;  // shadow: a is now 15
  b = b + 10;     // reassign: b is now 30
  {
    let c = 100;  // scoped: c only exists here
  }
  return a + b;
}
